let extractedText = "";

// Función recursiva para buscar cualquier 'textRun' en el laberinto de Google Docs
function extractText(element) {
    if (!element) return;

    // Si encontramos un pedazo de texto, lo concatenamos
    if (element.textRun && element.textRun.content) {
        extractedText += element.textRun.content;
    }

    // Si es un arreglo (como elements o tableCells), iteramos por cada uno
    if (Array.isArray(element)) {
        element.forEach(extractText);
    }
    // Si es un objeto, revisamos todas sus propiedades
    else if (typeof element === 'object') {
        for (const key in element) {
            if (Object.prototype.hasOwnProperty.call(element, key)) {
                extractText(element[key]);
            }
        }
    }
}

// Tomamos el JSON entero que mandó Google Docs y lo escaneamos
const docData = $input.first().json;
extractText(docData);

// Devolvemos únicamente el texto limpio
return [{
    json: {
        text: extractedText
    }
}];
